#include <iostream>#include <string>#include <fstream>#include <stdexcept>#include <curl/curl.h>static const std::string BASE_URL = "https://owenjz20.github.io";static void die(const std::string & msg) {    std::cerr << "[flowpm] error: " << msg << std::endl;    std::exit(1);}static size_t write_to_string(void * ptr, size_t size, size_t nmemb, void * userdata) {    size_t total = size * nmemb;    std::string * s = static_cast<std::string *>(userdata);    s->append(static_cast<char *>(ptr), total);    return total;}static void curl_init_once() {    static bool inited = false;    if (!inited) {        if (curl_global_init(CURL_GLOBAL_DEFAULT) != 0) {            die("curl_global_init failed");        }        inited = true;    }}static std::string http_get(const std::string & url) {    curl_init_once();    CURL * curl = curl_easy_init();    if (!curl) die("curl_easy_init failed");    std::string response;    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_to_string);    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);    CURLcode res = curl_easy_perform(curl);    if (res != CURLE_OK) {        std::string err = curl_easy_strerror(res);        curl_easy_cleanup(curl);        die("HTTP GET failed: " + err);    }    curl_easy_cleanup(curl);    return response;}static void http_download_to_file(const std::string & url, const std::string & path) {    curl_init_once();    CURL * curl = curl_easy_init();    if (!curl) die("curl_easy_init failed");    std::ofstream ofs(path, std::ios::binary);    if (!ofs) {        curl_easy_cleanup(curl);        die("failed to open file for writing: " + path);    }    auto write_cb = [](void * ptr, size_t size, size_t nmemb, void * userdata) -> size_t {        std::ofstream * ofs = static_cast<std::ofstream *>(userdata);        size_t total = size * nmemb;        ofs->write(static_cast<char *>(ptr), total);        return total;    };    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_cb);    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &ofs);    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);    CURLcode res = curl_easy_perform(curl);    ofs.close();    if (res != CURLE_OK) {        std::string err = curl_easy_strerror(res);        curl_easy_cleanup(curl);        die("HTTP download failed: " + err);    }    curl_easy_cleanup(curl);}static void cmd_list() {    // e.g. serve /packages.json from your GitHub Pages    std::string url = BASE_URL + "/packages.json";    std::string body = http_get(url);    std::cout << body << std::endl;}static void cmd_download(const std::string & name) {    // e.g. /packages/<name>.flpkg    std::string url  = BASE_URL + "/packages/" + name + ".flpkg";    std::string file = name + ".flpkg";    http_download_to_file(url, file);    std::cout << "Downloaded " << name << " to " << file << std::endl;}int main(int argc, char ** argv) {    if (argc < 2) {        std::cerr << "Usage:\n"                  << "  flowpm list\n"                  << "  flowpm download <name>\n";        return 1;    }    std::string cmd = argv[1];    if (cmd == "list") {        cmd_list();    } else if (cmd == "download") {        if (argc < 3) die("download requires <name>");        cmd_download(argv[2]);    } else {        die("unknown command: " + cmd);    }    return 0;}